css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 9px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 4px;}
.mz .rec-texto{font-size: 14px; line-height: 1.45;}
.mz .rec-texto b{font-size: 16px;}
.mz .rec-op{font-size: 18px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .calc-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 11px 34px;}
.mz .calc-grid.tres{grid-template-columns: repeat(3, 1fr);}
.mz .resp-fila{display: flex; align-items: center; gap: 7px; font-size: 18px; font-weight: 700; font-family: sans-serif; flex-wrap: wrap;}
.mz .resp-fila .lead{min-width: 86px;}
.mz .caja{width: 46px; height: 30px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block;}
.mz .caja-g{width: 54px; height: 34px;}
.mz .pista{font-family: sans-serif; font-size: 11.5px; font-weight: 600; color: #555; margin: -3px 0 8px;}
.mz .reparto{display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 26px;}
.mz .reparto-card{border: 1.8px solid var(--bosque); border-radius: 10px; padding: 8px 12px;}
.mz .reparto-card .tot{font-size: 15px; font-weight: 700; margin-bottom: 6px;}
.mz .grupos{display: flex; gap: 14px;}
.mz .grupo-caja{flex: 1; border: 1.5px dashed #000; border-radius: 8px; height: 42px;}
.mz .grupo-lbl{font-family: sans-serif; font-size: 10.5px; color: #555; text-align: center; margin-top: 2px;}
.mz .reparto-card .mit{font-size: 16px; font-weight: 700; font-family: sans-serif; margin-top: 7px; display: flex; align-items: center; gap: 7px;}
.mz .problema{border: 1.8px solid var(--bosque); border-radius: 10px; padding: 9px 13px; font-size: 14px; line-height: 1.4;}
.mz .problema .op-line{display: flex; align-items: center; gap: 10px; margin-top: 8px; font-size: 16px; font-weight: 700; font-family: sans-serif;}
.mz .problema .sol{border: 1.5px dashed #000; border-radius: 7px; min-height: 28px; flex: 1;}
.mz .problema,.mz .rec-texto{line-height: 1.725 !important;}
